function MaxProfit(prices: int[]) -> int {
  let n = prices.length();
  if (n == 0) {
    return 0;
  }
  let min_price = prices[0];
  let best = 0;
  let i = 1;
  while (i < n) {
    if (prices[i] < min_price) {
      min_price = prices[i];
    }
    let profit = prices[i] - min_price;
    if (profit > best) {
      best = profit;
    }
    i += 1;
  }
  return best;
}

